const fs=require("fs");
for (const f of ["09-transformer-overview.html","10-question-recap.html"]) {
  const s=fs.readFileSync(f,"utf8");
  const t=s.trim();
  console.log("=== "+f);
  console.log(" starts:", t.slice(0,10).replace(/\n/g,"\\n"), "| ends:", JSON.stringify(t.slice(-12)));
  console.log(" template tags:", (s.match(/<template>/g)||[]).length, (s.match(/<\/template>/g)||[]).length);
  console.log(" doctype/html/body:", /<!doctype|<html|<body|<head/i.test(s));
  console.log(" timelines reg:", (s.match(/__timelines\[/g)||[]).length, "| timelines paused:", (s.match(/timeline\(\{ paused: true \}\)/g)||[]).length);
  console.log(" gsap script:", /<script src="assets\/gsap.min.js"><\/script>/.test(s));
  console.log(" audio/img/http:", /<audio|<img|https?:\/\/(?!www\.w3\.org)/.test(s));
  console.log(" css transition:", /transition\s*:/.test(s), "| random:", /Math\.random/.test(s), "| yoyo/repeat:", /yoyo|repeat:/.test(s), "| date.now:", /Date\.now/.test(s));
  const clips=[...s.matchAll(/class="clip[^"]*"([^>]*)>/g)].map(m=>m[1]);
  console.log(" clips:", clips.length, clips.map(a=>/data-start/.test(a)&&/data-duration/.test(a)&&/data-track-index/.test(a)).join(","));
  console.log(" comp id:", (s.match(/data-composition-id="([^"]+)"/)||[])[1], "| font-face:", (s.match(/@font-face/g)||[]).length);
  const ids=[...s.matchAll(/id="([^"]+)"/g)].map(m=>m[1]);
  console.log(" ids not letter-first:", ids.filter(i=>!/^[a-zA-Z]/.test(i)).join(",") || "none");
  console.log(" font-size <28:", [...s.matchAll(/font-size:\s*(\d+)px/g)].map(m=>+m[1]).filter(v=>v<28).join(",") || "none");
}
'

